//go:build amd64 && !purego

package serpent

// The AVX2 kernels are generated by internal/genavx2 with go-asmgen, from the
// S-box expressions of sbox.go, into serpent_avx2_amd64.s. They process whole
// chunks of 8 (x8) or 16 (x16) blocks; n is the number of chunks (see
// generate.go).

//go:noescape
func encryptBlocksAVX2x8(rk *uint32, dst, src *byte, n int)

//go:noescape
func decryptBlocksAVX2x8(rk *uint32, dst, src *byte, n int)

//go:noescape
func encryptBlocksAVX2x16(rk *uint32, dst, src *byte, n int)

//go:noescape
func decryptBlocksAVX2x16(rk *uint32, dst, src *byte, n int)

// hasAVX2 is generated by amd64.FeatureProbe: the processor reports AVX2 AND
// the operating system saves the YMM state.
func hasAVX2() bool

// useAVX2 gates the kernels; the tests clear it to reach the pure-Go path.
var useAVX2 = hasAVX2()

// bulkBlocks runs as many whole 8-block chunks of src through the AVX2
// kernels as it can, and returns the number of bytes it did; the caller does
// the rest. dst must be at least as long as src, which is a multiple of 16.
func (c *serpentCipher) bulkBlocks(dst, src []byte, dec bool) int {
	if !useAVX2 {
		return 0
	}
	done := 0
	if n := len(src) / (16 * BlockSize); n > 0 {
		if dec {
			decryptBlocksAVX2x16(&c.rk[0], &dst[0], &src[0], n)
		} else {
			encryptBlocksAVX2x16(&c.rk[0], &dst[0], &src[0], n)
		}
		done = n * 16 * BlockSize
	}
	if len(src)-done >= 8*BlockSize {
		if dec {
			decryptBlocksAVX2x8(&c.rk[0], &dst[done], &src[done], 1)
		} else {
			encryptBlocksAVX2x8(&c.rk[0], &dst[done], &src[done], 1)
		}
		done += 8 * BlockSize
	}
	return done
}
